import fs from "node:fs";
import { fileURLToPath } from "node:url";
import type { Builder } from "@sveltejs/kit";
const __dirname = fileURLToPath(new URL(".", import.meta.url));
import { build } from "esbuild";
import * as path from "path";
import { cp, rm, } from "fs/promises";
import { existsSync } from "node:fs";
import archiver from 'archiver';
import { uploadToS3, deployLambdaFunction, setupCloudFrontTrigger, invalidateCache } from "./aws.js";

/**
 * Configuration options for connecting to an S3 bucket.
 */
interface S3Config {
	/**
	 * The name of the S3 bucket to use.
	 */
	bucketName: string;
	/**
	 * The prefix to use for all object keys in the bucket.
	 */
	prefix: string;
	/**
	 * The AWS region where the S3 bucket is located.
	 */
	region: string;
}

/**
 * Configuration options for AWS Lambda function.
 */
interface LambdaConfig {
	/**
	 * Name of the AWS Lambda function.
	 */
	functionName: string;
	/**
	 * AWS region where the Lambda function is deployed.
	 */
	region: string;
}

/**
 * Configuration options for the AWS CloudFront adapter.
 */
interface CloudFrontConfig {
	/**
	 * The ID of the CloudFront distribution to use.
	 */
	distributionId: string;
	/**
	 * The AWS region in which the CloudFront distribution is located.
	 */
	region: string;
}

/**
 * Configuration object for AWS services.
 */
interface AWSConfiguration {
	/**
	 * Configuration object for Amazon S3.
	 */
	s3: S3Config;
	/**
	 * Configuration object for AWS Lambda.
	 */
	lambda: LambdaConfig;
	/**
	 * Configuration object for Amazon CloudFront.
	 */
	cloudfront: CloudFrontConfig;
}

/**
 * Default configuration for AWS resources.
 */
const defaultConfig: AWSConfiguration = {
	s3 : { bucketName : "", prefix : "", region : "ap-south-1"},
	lambda: { functionName : "", region : "us-east-1"},
	cloudfront: { distributionId : "", region : "us-east-1"}
}

/**
 * Compresses a directory into a zip file.
 * @param source - The path of the directory to be compressed.
 * @param out - The path of the output zip file.
 * @returns A Promise that resolves when the compression is complete.
 */
async function zipDirectory(source: string, out: string): Promise<void> {
	const archive = archiver('zip', { zlib: { level: 9 } });  // Sets the compression level.
	console.log("Zipping....", source, out);
	const stream = fs.createWriteStream(out);

	return new Promise((resolve, reject) => {
			const outputFileName = path.basename(out);  // Extract the file name from the output path

			archive
					.glob('**/*', {
							cwd: source,
							ignore: [outputFileName]  // Ignore the file with the name specified in the out parameter
					})
					.on('error', err => reject(err))
					.pipe(stream);

			stream.on('close', () => resolve());
			archive.finalize();
	});
}

/**
 * Bundles the SvelteKit app for deployment to AWS Lambda.
 * @returns {Promise<void>}
 */
async function bundleApp() {
  await rm(path.join("build"), { recursive: true, force: true });
  await build({
    entryPoints: [path.join("out", "server", "lambda-handler", "index.js")],
    bundle: true,
    platform: "node",
    target: ["esnext"],
    format: "esm",
    outExtension: {
      ".js": ".mjs",
    },
    banner: {
      js: [
        `import { createRequire as topLevelCreateRequire } from 'module';`,
        `const require = topLevelCreateRequire(import.meta.url);`,
      ].join(""),
    },
    outdir: path.join("build"),
  });
  if (existsSync(path.join("out", "prerendered"))) {
    await cp(path.join("out", "prerendered"), path.join("build", "prerendered"), {
      recursive: true,
    });
  }else{
    console.log("No Prerendered Directory found.");
  }
  console.log("BUILD SUCEEDED!");
}


/**
 * AWS adapter function for SvelteKit
 * @param configInput - Configuration object for AWS
 * @returns SvelteKit adapter object
 */
function adapter(configInput: AWSConfiguration) {
  const adapter = {
    name: "@juspay/sveltekit-aws-adapter",
    async adapt(builder: Builder) {
			console.log("Building...");

      const out = path.join("out");
      const clientDir = path.join(out, "client");
      const serverDir = path.join(out, "server");
      const prerenderedDir = path.join(out, "prerendered");

			const config: AWSConfiguration = deepMerge(defaultConfig, configInput) as AWSConfiguration;

      // Cleanup output folder
      builder.rimraf(out);

      // Create static output
      builder.log.minor("Copying assets...");
      builder.writeClient(clientDir);
      const prerenderedFiles = builder.writePrerendered(prerenderedDir);

      // Create Lambda function
      builder.log.minor("Generating server function...");
      builder.writeServer(serverDir);
      // copy over handler files in server handler folder
      builder.copy(
        path.join(__dirname, "handler"),
        path.join(serverDir, "lambda-handler")
      );
      // save a list of files in server handler folder
      fs.writeFileSync(
        path.join(serverDir, "lambda-handler", "prerendered-file-list.js"),
        `export default ${JSON.stringify(prerenderedFiles)}`
      );
			await bundleApp();

			await uploadToS3(clientDir, config.s3.bucketName, config.s3.prefix, config.s3.region);

			await zipDirectory(path.join("build"), path.join("build")+"/lambda.zip")
			.then(() => console.log('Directory successfully zipped!'))
			.catch(error => console.error('Failed to zip directory:', error));

			const lambdaVersion = await deployLambdaFunction(config.lambda.functionName, path.join("build")+"/lambda.zip", config.lambda.region);
			if (lambdaVersion !== undefined){
				await setupCloudFrontTrigger(config.lambda.functionName, lambdaVersion, config.cloudfront.distributionId, config.cloudfront.region);
			}

			await invalidateCache(config.cloudfront.distributionId, ["/*"], config.cloudfront.region);
    },
  };

  return adapter;
}

interface AnyObject {
  [key: string]: any;
}

/**
 * Recursively merges two objects into a single object.
 * @param target - The target object to merge into.
 * @param source - The source object to merge from.
 * @returns The merged object.
 * @throws An error if either target or source is not an object.
 */
function deepMerge(target: AnyObject, source: AnyObject): AnyObject {
  const isObject = (obj: any) => obj && typeof obj === 'object';

  if (!isObject(target) || !isObject(source)) {
    throw new Error('Invalid arguments: Both target and source must be objects');
  }

  Object.keys(source).forEach(key => {
    const targetValue = target[key];
    const sourceValue = source[key];

    if (isObject(targetValue) && isObject(sourceValue)) {
      target[key] = deepMerge(Object.assign({}, targetValue), sourceValue);
    } else {
      target[key] = sourceValue ? sourceValue : targetValue;
    }
  });

  return target;
}

export { adapter, AWSConfiguration };

import fs from "node:fs";
import * as path from "path";
import { S3Client, PutObjectCommand } from "@aws-sdk/client-s3";
import { LambdaClient, GetFunctionConfigurationCommand, UpdateFunctionCodeCommand, PublishVersionCommand } from "@aws-sdk/client-lambda";
import { CloudFrontClient, GetDistributionConfigCommand, UpdateDistributionCommand, UpdateDistributionCommandInput, LambdaFunctionAssociation, CreateInvalidationCommand } from "@aws-sdk/client-cloudfront";
import * as mime from 'mime-types';

// Lambda@Edge functions must be created in the N. Virginia region.

/**
 * Uploads all files in a directory to an S3 bucket with the specified prefix.
 * @param directoryPath - The path to the directory containing the files to upload.
 * @param bucketName - The name of the S3 bucket to upload the files to.
 * @param s3Prefix - The prefix to add to the S3 object keys.
 * @param region - The AWS region where the S3 bucket is located.
 */
async function uploadToS3(directoryPath: string, bucketName: string, s3Prefix: string, region: string) {
  const items = fs.readdirSync(directoryPath);
	const s3 = new S3Client({ region: region });
  const prefix = s3Prefix && s3Prefix.length>0? s3Prefix+ "/" : "";
  for (const item of items) {
    const itemPath = path.join(directoryPath, item);
    const stats = fs.statSync(itemPath);
    if (stats.isFile()) {
      const fileStream = fs.createReadStream(itemPath);
	  const contentType = mime.lookup(itemPath) || 'application/octet-stream';
      const s3Params = {
        Bucket: bucketName,
        Key: `${prefix}${path.relative(directoryPath, itemPath).replace(/\\/g, '/')}`,
        Body: fileStream,
		ContentType: contentType
      };
      try {
        await s3.send(new PutObjectCommand(s3Params));
        console.log(`Successfully uploaded ${itemPath} to ${bucketName}/${prefix}${path.relative(directoryPath, itemPath).replace(/\\/g, '/')}`);
      } catch (error) {
        console.error(`Failed to upload ${itemPath}:`, error);
      }
    } else if (stats.isDirectory()) {
      await uploadToS3(itemPath, bucketName, `${prefix}${item}`, region);
    }
  }
}

/**
 * Deploys a Lambda function with the given name and zip file path to the specified region.
 * @param functionName - The name of the Lambda function to deploy.
 * @param zipFilePath - The file path of the zip file containing the Lambda function code.
 * @param region - The AWS region to deploy the Lambda function to.
 * @returns The version of the deployed Lambda function.
 */
async function deployLambdaFunction(functionName: string, zipFilePath: string, region: string) {
	console.log("Reading zip file...", functionName ,zipFilePath);
	const zipFile = fs.readFileSync(zipFilePath);
	const updateCodeParams = {
			FunctionName: functionName,
			ZipFile: zipFile
	};
	const lambda = new LambdaClient({ region });
	console.log("Updating Lambda Function...");
	try {
			await lambda.send(new UpdateFunctionCodeCommand(updateCodeParams));
			console.log('Lambda function code updated successfully.');
	} catch (error) {
			console.error(`Failed to update function code: ${error}`);
			throw error;
	}

	console.log('Waiting for update to complete...');
    await new Promise(resolve => setTimeout(resolve, 5000));

    try {
        const publishVersionParams = {
            FunctionName: functionName,
        };
        const { Version } = await lambda.send(new PublishVersionCommand(publishVersionParams));
        console.log(`Lambda function version ${Version} published successfully.`);
        return Version;
    } catch (error) {
        console.error(`Failed to publish function version: ${error}`);
        throw error;
    }
}

/**
 * Sets up a CloudFront trigger for a Lambda function.
 * @param functionName - The name of the Lambda function.
 * @param functionVersion - The version of the Lambda function.
 * @param distributionId - The ID of the CloudFront distribution.
 * @param region - The AWS region in which the resources are located.
 * @throws An error if the DistributionConfig or DefaultCacheBehavior is missing.
 */
async function setupCloudFrontTrigger(functionName: string, functionVersion: string, distributionId: string, region: string) {
    try {
        // Get the current distribution configuration
				const lambda = new LambdaClient({ region });
				const cloudFront = new CloudFrontClient({ region });
        const getDistConfigCommand = new GetDistributionConfigCommand({ Id: distributionId });
        const { DistributionConfig } = await cloudFront.send(getDistConfigCommand);

        // Ensure that DistributionConfig and DefaultCacheBehavior are defined
        if (!DistributionConfig || !DistributionConfig.DefaultCacheBehavior) {
            throw new Error('Missing DistributionConfig or DefaultCacheBehavior');
        }

        // Get the Lambda function ARN
        const getFunctionConfigCommand = new GetFunctionConfigurationCommand({ FunctionName: functionName });
        const { FunctionArn } = await lambda.send(getFunctionConfigCommand);
        const lambdaFunctionArn = `${FunctionArn}:${functionVersion}`;

        // Update the distribution configuration to add the new Lambda function association
        const newAssociation: LambdaFunctionAssociation = {
            EventType: "origin-request",
            LambdaFunctionARN: lambdaFunctionArn,
        };
        const existingAssociations = DistributionConfig.DefaultCacheBehavior.LambdaFunctionAssociations?.Items || [];
		const updatedAssociations = existingAssociations.filter(
			association => association.EventType !== 'origin-request'
		);
		updatedAssociations.push(newAssociation);
        const updatedLambdaFunctionAssociations = {
            Quantity: updatedAssociations.length,
            Items: updatedAssociations,
        };

        const updatedDistributionConfig: UpdateDistributionCommandInput = {
            Id: distributionId,
            DistributionConfig: {
                ...DistributionConfig,
                DefaultCacheBehavior: {
                    ...DistributionConfig.DefaultCacheBehavior,
                    LambdaFunctionAssociations: updatedLambdaFunctionAssociations,
                },
            },
            IfMatch: (await cloudFront.send(getDistConfigCommand)).ETag,  // Include the ETag to ensure the distribution configuration hasn't changed since it was fetched
        };
        await cloudFront.send(new UpdateDistributionCommand(updatedDistributionConfig));
        console.log('CloudFront trigger set up successfully.');
    } catch (error) {
        console.error(`Failed to set up CloudFront trigger: ${error}`);
        throw error;
    }
}

/**
 * Invalidates the cache for the specified paths in the specified CloudFront distribution.
 * @param distributionId The ID of the CloudFront distribution to invalidate the cache for.
 * @param paths An array of paths to invalidate the cache for.
 * @param region The AWS region where the CloudFront distribution is located.
 * @returns A Promise that resolves when the invalidation is complete.
 * @throws An error if the invalidation fails.
 */
async function invalidateCache(distributionId: string, paths: string[], region: string): Promise<void> {
	const invalidationBatch = {
	  Paths: {
		Quantity: paths.length,
		Items: paths,
	  },
	  CallerReference: new Date().toISOString(),
	};

	const params = {
	  DistributionId: distributionId,
	  InvalidationBatch: invalidationBatch,
	};
	const cloudFront = new CloudFrontClient({ region });

	try {
	  const result = await cloudFront.send(new CreateInvalidationCommand(params));
	  if (result.Invalidation) {
	    console.log(`Invalidation created with ID: ${result.Invalidation.Id}`);
	  }
	} catch (error) {
	  console.error(`Failed to create invalidation: ${error}`);
	  throw error;
	}
}

export { uploadToS3, deployLambdaFunction, setupCloudFrontTrigger, invalidateCache };

import fs from 'node:fs';
import path from 'node:path';
import { installPolyfills } from '@sveltejs/kit/node/polyfills';
import { Server as ServerType } from '@sveltejs/kit';
// @ts-ignore
import { Server } from '../index.js';
// @ts-ignore
import { manifest } from '../manifest.js';
// @ts-ignore
import prerenderedFiles from './prerendered-file-list.js';
import type {
	APIGatewayProxyEventV2,
	APIGatewayProxyEvent,
	CloudFrontRequestEvent
} from 'aws-lambda';
import { InternalEvent, convertFrom, convertTo } from './event-mapper.js';

import { isBinaryContentType } from './binary.js';

installPolyfills();

const app: ServerType = new Server(manifest);
await app.init({ env: process.env as Record<string, string> });

export async function handler(
	event: APIGatewayProxyEventV2 | CloudFrontRequestEvent | APIGatewayProxyEvent
) {
	// Parse Lambda event
	const internalEvent = convertFrom(event);

	// Set correct host header
	if (internalEvent.headers['x-forwarded-host']) {
		internalEvent.headers.host = internalEvent.headers['x-forwarded-host'];
	}

	// Check request is for prerendered file
	if (internalEvent.method === 'GET') {
		const filePath = isPrerenderedFile(internalEvent.rawPath);
		if (filePath) {
			return internalEvent.type === 'cf'
				? formatCloudFrontPrerenderedResponse(event as CloudFrontRequestEvent, filePath)
				: formatAPIGatewayPrerenderedResponse(internalEvent, filePath);
		}
	}

	// Process request
	const requestUrl = `https://${internalEvent.headers.host}${internalEvent.url}`;
	const requestProps = {
		method: internalEvent.method,
		headers: internalEvent.headers,
		body: ['GET', 'HEAD'].includes(internalEvent.method) ? undefined : internalEvent.body
	};

	const request = new Request(requestUrl, requestProps);
	const response: Response = await app.respond(request, {
		getClientAddress: () => internalEvent.remoteAddress
	});

	//Parse the response into lambda proxy response
	if (response) {
		const headers: Record<string, string[]> = {};
		response.headers.forEach((value, key) => {
			headers[key] = headers[key] || [];
			headers[key].push(value);
		});
		const isBase64Encoded = isBinaryContentType(
			Array.isArray(headers['content-type']) ? headers['content-type'][0] : headers['content-type']
		);
		const body = isBase64Encoded
			? Buffer.from(await response.arrayBuffer()).toString('base64')
			: await response.text();
		return convertTo({
			type: internalEvent.type,
			statusCode: response.status,
			headers,
			isBase64Encoded,
			body
		});
	}
	return {
		statusCode: 404,
		body: 'Not found.'
	};
}

function isPrerenderedFile(uri: string) {
	// remove leading and trailing slashes
	uri = uri.replace(/^\/|\/$/g, '');

	if (uri === '') {
		return prerenderedFiles.includes('index.html') ? 'index.html' : undefined;
	}

	if (prerenderedFiles.includes(uri)) {
		return uri;
	}
	if (prerenderedFiles.includes(uri + '/index.html')) {
		return uri + '/index.html';
	}
	if (prerenderedFiles.includes(uri + '.html')) {
		return uri + '.html';
	}
}

function formatCloudFrontPrerenderedResponse(event: CloudFrontRequestEvent, filePath: string) {
	const request = event.Records[0].cf.request;
	request.uri = `/${filePath}`;
	return request;
}

function formatAPIGatewayPrerenderedResponse(internalEvent: InternalEvent, filePath: string) {
	return convertTo({
		type: internalEvent.type,
		statusCode: 200,
		headers: {
			'content-type': 'text/html',
			'cache-control': 'public, max-age=0, s-maxage=31536000, must-revalidate'
		},
		isBase64Encoded: false,
		body: fs.readFileSync(path.join('prerendered', filePath), 'utf8')
	});
}

import type {
  APIGatewayProxyEventV2,
  APIGatewayProxyResultV2,
  APIGatewayProxyEvent,
  APIGatewayProxyResult,
  CloudFrontRequestEvent,
  CloudFrontRequestResult,
  CloudFrontHeaders,
} from "aws-lambda";

export type InternalEvent = {
  readonly type: "v1" | "v2" | "cf";
  readonly method: string;
  readonly rawPath: string;
  readonly url: string;
  readonly body: Buffer;
  readonly headers: Record<string, string>;
  readonly remoteAddress: string;
};

type InternalResult = {
  readonly type: "v1" | "v2" | "cf";
  statusCode: number;
  headers: Record<string, string | string[]>;
  body: string;
  isBase64Encoded: boolean;
};

export function isAPIGatewayProxyEventV2(
  event: any
): event is APIGatewayProxyEventV2 {
  return event.version === "2.0";
}

export function isAPIGatewayProxyEvent(
  event: any
): event is APIGatewayProxyEvent {
  return event.version === undefined && !isCloudFrontRequestEvent(event);
}

export function isCloudFrontRequestEvent(
  event: any
): event is CloudFrontRequestEvent {
  return event.Records !== undefined;
}

export function convertFrom(
  event: APIGatewayProxyEventV2 | APIGatewayProxyEvent | CloudFrontRequestEvent
): InternalEvent {
  if (isCloudFrontRequestEvent(event)) {
    return convertFromCloudFrontRequestEvent(event);
  } else if (isAPIGatewayProxyEventV2(event)) {
    return convertFromAPIGatewayProxyEventV2(event);
  } else if (isAPIGatewayProxyEvent(event)) {
    return convertFromAPIGatewayProxyEvent(event);
  }
  throw new Error("Unsupported event type");
}

export function convertTo(
  result: InternalResult
): APIGatewayProxyResultV2 | APIGatewayProxyResult | CloudFrontRequestResult {
  if (result.type === "v2") {
    return convertToApiGatewayProxyResultV2(result);
  } else if (result.type === "v1") {
    return convertToApiGatewayProxyResult(result);
  } else if (result.type === "cf") {
    return convertToCloudFrontRequestResult(result);
  }
  throw new Error("Unsupported event type");
}

function convertFromAPIGatewayProxyEvent(
  event: APIGatewayProxyEvent
): InternalEvent {
  const { path, body, httpMethod, requestContext, isBase64Encoded } = event;
  return {
    type: "v1",
    method: httpMethod,
    rawPath: path,
    url: path + normalizeAPIGatewayProxyEventQueryParams(event),
    body: Buffer.from(body ?? "", isBase64Encoded ? "base64" : "utf8"),
    headers: normalizeAPIGatewayProxyEventHeaders(event),
    remoteAddress: requestContext.identity.sourceIp,
  };
}

function convertFromAPIGatewayProxyEventV2(
  event: APIGatewayProxyEventV2
): InternalEvent {
  const { rawPath, rawQueryString, requestContext } = event;
  return {
    type: "v2",
    method: requestContext.http.method,
    rawPath,
    url: rawPath + (rawQueryString ? `?${rawQueryString}` : ""),
    body: normalizeAPIGatewayProxyEventV2Body(event),
    headers: normalizeAPIGatewayProxyEventV2Headers(event),
    remoteAddress: requestContext.http.sourceIp,
  };
}

function convertFromCloudFrontRequestEvent(
  event: CloudFrontRequestEvent
): InternalEvent {
  const { method, uri, querystring, body, headers, clientIp } =
    event.Records[0].cf.request;
  return {
    type: "cf",
    method,
    rawPath: uri,
    url: uri + (querystring ? `?${querystring}` : ""),
    body: Buffer.from(
      body?.data ?? "",
      body?.encoding === "base64" ? "base64" : "utf8"
    ),
    headers: normalizeCloudFrontRequestEventHeaders(headers),
    remoteAddress: clientIp,
  };
}

function convertToApiGatewayProxyResult(
  result: InternalResult
): APIGatewayProxyResult {
  const headers: Record<string, string> = {};
  const multiValueHeaders: Record<string, string[]> = {};
  Object.entries(result.headers).forEach(([key, value]) => {
    if (Array.isArray(value)) {
      multiValueHeaders[key] = value;
    } else {
      if (value === null) {
        headers[key] = "";
        return;
      }
      headers[key] = value;
    }
  });
  const response: APIGatewayProxyResult = {
    statusCode: result.statusCode,
    headers,
    body: result.body,
    isBase64Encoded: result.isBase64Encoded,
    multiValueHeaders,
  };

  return response;
}

function convertToApiGatewayProxyResultV2(
  result: InternalResult
): APIGatewayProxyResultV2 {
  const headers: Record<string, string> = {};
  Object.entries(result.headers)
    .filter(([key]) => key.toLowerCase() !== "set-cookie")
    .forEach(([key, value]) => {
      if (value === null) {
        headers[key] = "";
        return;
      }
      headers[key] = Array.isArray(value) ? value.join(", ") : value.toString();
    });
  const response: APIGatewayProxyResultV2 = {
    statusCode: result.statusCode,
    headers,
    cookies: result.headers["set-cookie"] as string[] | undefined,
    body: result.body,
    isBase64Encoded: result.isBase64Encoded,
  };

  return response;
}

function convertToCloudFrontRequestResult(
  result: InternalResult
): CloudFrontRequestResult {
  const headers: CloudFrontHeaders = {};
  Object.entries(result.headers)
    .filter(([key]) => key.toLowerCase() !== "content-length")
    .forEach(([key, value]) => {
      headers[key] = [
        ...(headers[key] || []),
        ...(Array.isArray(value)
          ? value.map((v) => ({ key, value: v }))
          : [{ key, value: value.toString() }]),
      ];
    });
  const response: CloudFrontRequestResult = {
    status: result.statusCode.toString(),
    statusDescription: "OK",
    headers,
    bodyEncoding: result.isBase64Encoded ? "base64" : "text",
    body: result.body,
  };

  return response;
}

function normalizeAPIGatewayProxyEventV2Headers(
  event: APIGatewayProxyEventV2
): Record<string, string> {
  const { headers: rawHeaders, cookies } = event;

  const headers: Record<string, string> = {};

  if (Array.isArray(cookies)) {
    headers["cookie"] = cookies.join("; ");
  }

  for (const [key, value] of Object.entries(rawHeaders || {})) {
    headers[key.toLowerCase()] = value!;
  }

  return headers;
}

function normalizeAPIGatewayProxyEventV2Body(
  event: APIGatewayProxyEventV2
): Buffer {
  const { body, isBase64Encoded } = event;
  if (Buffer.isBuffer(body)) {
    return body;
  } else if (typeof body === "string") {
    return Buffer.from(body, isBase64Encoded ? "base64" : "utf8");
  } else if (typeof body === "object") {
    return Buffer.from(JSON.stringify(body));
  }
  return Buffer.from("", "utf8");
}

function normalizeAPIGatewayProxyEventQueryParams(
  event: APIGatewayProxyEvent
): string {
  const params = new URLSearchParams();
  if (event.multiValueQueryStringParameters) {
    for (const [key, value] of Object.entries(
      event.multiValueQueryStringParameters
    )) {
      if (value !== undefined) {
        for (const v of value) {
          params.append(key, v);
        }
      }
    }
  }
  if (event.queryStringParameters) {
    for (const [key, value] of Object.entries(event.queryStringParameters)) {
      if (value !== undefined) {
        params.append(key, value);
      }
    }
  }
  const value = params.toString();
  return value ? `?${value}` : "";
}

function normalizeAPIGatewayProxyEventHeaders(
  event: APIGatewayProxyEvent
): Record<string, string> {
  event.multiValueHeaders;
  const headers: Record<string, string> = {};

  for (const [key, values] of Object.entries(event.multiValueHeaders)) {
    if (values) {
      headers[key.toLowerCase()] = values.join(",");
    }
  }
  for (const [key, value] of Object.entries(event.headers)) {
    if (value) {
      headers[key.toLowerCase()] = value;
    }
  }
  return headers;
}

function normalizeCloudFrontRequestEventHeaders(
  rawHeaders: CloudFrontHeaders
): Record<string, string> {
  const headers: Record<string, string> = {};

  for (const [key, values] of Object.entries(rawHeaders)) {
    for (const { value } of values) {
      if (value) {
        headers[key.toLowerCase()] = value;
      }
    }
  }

  return headers;
}
